cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Find user by email
const user = db.prepare(\"SELECT * FROM users WHERE email = 'maya.chen@example.com'\").get();
console.log('=== USER RECORD ===');
console.log(JSON.stringify(user, null, 2));

if (user) {
  // Get payment methods
  console.log('\n=== PAYMENT METHODS ===');
  const pms = db.prepare('SELECT * FROM rt_payment_methods WHERE user_id = ?').all(user.user_id);
  pms.forEach(pm => console.log(JSON.stringify(pm, null, 2)));

  // Get orders
  console.log('\n=== ORDERS ===');
  const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id = ?\").all(user.user_id);
  orders.forEach(o => console.log(JSON.stringify(o, null, 2)));

  // Get cart
  console.log('\n=== CART ===');
  const cart = db.prepare('SELECT * FROM carts WHERE customer_id = ?').get(user.user_id);
  console.log(JSON.stringify(cart, null, 2));

  // Get cart items if any
  if (cart) {
    const itemIds = JSON.parse(cart.item_ids_json || '[]');
    if (itemIds.length > 0) {
      console.log('\n=== CART ITEMS ===');
      const placeholders = itemIds.map(() => '?').join(',');
      const items = db.prepare('SELECT * FROM cart_items WHERE ci_id IN (' + placeholders + ')').all(...itemIds);
      items.forEach(i => console.log(JSON.stringify(i, null, 2)));
    }
  }

  // Check loyalty / account fields
  console.log('\n=== ALL USER COLUMNS ===');
  const cols = db.prepare('PRAGMA table_info(users)').all();
  cols.forEach(c => console.log(c.name, ':', user[c.name]));
}
"

